  assert.equals("reina malvada", espejoMagico.quienEsLaMasBellaDelReino())
}

test "cuando pasa el tiempo, la más bella del reino es Blancanieves" {
  espejoMagico.pasoElTiempo()
  assert.equals("Blancanieves", espejoMagico.quienEsLaMasBellaDelReino())
}

