ejercicios.extra:
object buenosAires {
  method kilometro() = 0
}

object santaFe {
  method kilometro() = 315
}

object rosario {
  method kilometro() = 514
}

object mercedes {
  method cantar() = "♪ una voz antigua de viento y de sal ♫"
}

object anastasia {
  method cantar() = "priiiip priiiip"
  method volarEnCirculos() {}
  method comerLombriz() {}
}

object pepita {
  var energia = 100
  var ciudad = rosario

  method energia(unaEnergia) { energia = unaEnergia }
  method energia() = energia
  method ciudad() = ciudad
  method cantar() = "pri pri pri"
  method comerLombriz() { energia += 20 }
  method comerAlpiste(gramos) { energia += gramos * 15 }
  method volarEnCirculos() { energia -= 10 }
  method estasFeliz() = energia > 90
  method volarHacia(unaCiudad) {
    energia -= self.distancia(unaCiudad) * 3
    ciudad = unaCiudad
  }
  method distancia(unaCiudad) = (ciudad.kilometro() - unaCiudad.kilometro()).abs()
  method comerAlpisteYVolarHacia(gramos, unaCiudad) {
    self.comerAlpiste(gramos)
    self.volarHacia(unaCiudad)
  }
}

