  }
  test "cuentan sus reparaciones" {
    const reparador = new Reparador(numeroDeSerie = 2)
    assert.equals(0, reparador.reparaciones())
    reparador.trabajar(1)
    reparador.trabajar(2)
    assert.equals(2, reparador.reparaciones())
  }
}

