}

describe "el desgaste" {
  test "tiene su número" {
    assert.equals(7, new Telar(numero = 7).numero())
  }
  test "tejer desgasta" {
    const t = new Telar(numero = 1)
    t.tejer()
    t.tejer()
    assert.equals(20, t.desgaste())
    assert.notThat(t.necesitaArreglo())
  }
  test "con 30, hay que arreglarlo" {
    const t = new Telar(numero = 1)
    3.times({ i => t.tejer() })
    assert.that(t.necesitaArreglo())
  }
  test "arreglar lo deja en 0" {
    const t = new Telar(numero = 1)
    t.tejer()
    t.arreglar()
    assert.equals(0, t.desgaste())
  }
}

describe "la presión" {
  test "tiene su límite" {
    assert.equals(20, new Caldera(limite = 20).limite())
  }
  test "en el límite no es peligrosa" {
    const c = new Caldera(limite = 10)
    c.echarCarbon()
    c.echarCarbon()
    assert.equals(10, c.presion())
    assert.notThat(c.esPeligrosa())
  }
  test "pasándose, sí" {
    const c = new Caldera(limite = 10)
    3.times({ i => c.echarCarbon() })
    assert.that(c.esPeligrosa())
  }
  test "soltar vapor la deja en 0" {
    const c = new Caldera(limite = 10)
    c.echarCarbon()
    c.soltarVapor()
    assert.equals(0, c.presion())
  }
}

