class AnilloTrabadoException inherits DomainException {}

object anillo {
  var trabado = false
  method trabar() {
    trabado = true
  }
  method detenerse() {
    if (trabado) {
      throw new AnilloTrabadoException(message = "Anillo trabado")
    }
  }
}

object consola {
  var apagada = false
  method apagada() = apagada
}

ejercicios.tests:
describe "la consola" {
  test "con el código, apaga" {
    consola.apagar(742)
    assert.that(consola.apagada())
  }
  test "con otro código es un error" {
    assert.throwsExceptionWithMessage("Código incorrecto", { consola.apagar(1111) })
    assert.notThat(consola.apagada())
  }
  test "si el anillo falla, no queda apagada a medias" {
    anillo.trabar()
    assert.throwsException({ consola.apagar(742) })
    assert.notThat(consola.apagada())
  }
  test "intentar apagar" {
    assert.equals("Apagado", consola.intentarApagar(742))
  }
  test "intentar con otro código" {
    assert.equals("No se pudo: Código incorrecto", consola.intentarApagar(1111))
  }
  test "intentar con el anillo trabado" {
    anillo.trabar()
    assert.equals("No se pudo: Anillo trabado", consola.intentarApagar(742))
  }
}

